using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Production;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Production;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Production;
#pragma warning disable CA1862,CA1725
public sealed class ProductionAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,Application.Abstractions.Actors.ICurrentActor current,IAuditWriter audit,TimeProvider time):IProductionAdministration
{
 private Guid Company=>company.RequireCompanyId();private Guid Actor=>Guid.TryParse(current.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Actor required");private DateTimeOffset Now=>time.GetUtcNow();
 public Task<Result<IReadOnlyList<ProductionJobView>>>GenerateAsync(GenerateProductionJobsCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Order?order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==c.OrderId,t);if(order is null)return Result.Failure<IReadOnlyList<ProductionJobView>>(ProductionErrors.NotFound);if(order.Status!=OrderStatus.Submitted)return Result.Failure<IReadOnlyList<ProductionJobView>>(ProductionErrors.OrderNotEligible);List<ProductionJob>made=[];foreach(OrderItem item in await db.OrderItems.Where(x=>x.OrderId==order.Id&&x.IsActive).ToListAsync(t)){await Add(item,null,ProductionJobType.DesignPreparation,null,null,made,t);foreach(OrderPrintOperation op in await db.OrderPrintOperations.Where(x=>x.OrderItemId==item.Id&&x.IsActive).ToListAsync(t))await Add(item,op.Id,ProductionJobType.Print,op.ArtworkVersionId,op.FileVersionId,made,t);await Add(item,null,ProductionJobType.HeatPress,null,null,made,t);}return Result.Success<IReadOnlyList<ProductionJobView>>(made.Select(View).ToArray());},ct);
 private async Task Add(OrderItem item,Guid?op,ProductionJobType type,Guid?artwork,Guid?file,List<ProductionJob>result,CancellationToken t){string key=ProductionText.Key(item.Id,type,op);ProductionJob?existing=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.GenerationKey==key,t);if(existing is not null){result.Add(existing);return;}ProductionJob j=ProductionJob.Create(Company,item.OrderId,item.Id,op,type,artwork,file,Now).Value;db.Add(j);History(j,"Created",null);Log("production.job.created",j.Id);result.Add(j);}
 public Task<Result<ProductionJobView>>GetAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);return j is null?Result.Failure<ProductionJobView>(ProductionErrors.NotFound):Result.Success(View(j));},ct);
 public Task<Result<ProductionPage>>QueueAsync(ProductionQueueQuery q,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(q.Page<1||q.PageSize is<1 or>100)return Result.Failure<ProductionPage>(ProductionErrors.Invalid);IQueryable<ProductionJob>x=db.ProductionJobs.AsNoTracking();if(q.Status is not null)x=x.Where(j=>j.Status==q.Status);if(q.JobType is not null)x=x.Where(j=>j.JobType==q.JobType);if(q.OperatorUserId is not null)x=x.Where(j=>j.AssignedOperatorUserId==q.OperatorUserId);if(q.EquipmentId is not null)x=x.Where(j=>j.AssignedEquipmentId==q.EquipmentId);if(q.Priority is not null)x=x.Where(j=>j.Priority==q.Priority);if(q.PlannedDate is not null){DateTimeOffset from=new(q.PlannedDate.Value.ToDateTime(TimeOnly.MinValue),TimeSpan.Zero),to=from.AddDays(1);x=x.Where(j=>j.PlannedStartUtc>=from&&j.PlannedStartUtc<to);}if(q.BranchId is not null)x=from j in x join e in db.Equipment on j.AssignedEquipmentId equals e.Id where e.BranchId==q.BranchId select j;long total=await x.LongCountAsync(t);List<ProductionJob>rows=await x.OrderByDescending(j=>j.Priority).ThenBy(j=>j.QueuePosition).ThenBy(j=>j.PlannedStartUtc).ThenBy(j=>j.CreatedAtUtc).ThenBy(j=>j.Id).Skip((q.Page-1)*q.PageSize).Take(q.PageSize).ToListAsync(t);return Result.Success(new ProductionPage(rows.Select(View).ToArray(),q.Page,q.PageSize,total));},ct);
 public Task<Result<IReadOnlyList<EquipmentCapacityView>>>CapacityAsync(DateTimeOffset?from,DateTimeOffset?to,CancellationToken ct)=>tx.ExecuteAsync(async t=>{DateTimeOffset f=from??Now.Date,u=to??f.AddDays(7);if(u<=f)return Result.Failure<IReadOnlyList<EquipmentCapacityView>>(ProductionErrors.Invalid);var equipment=await db.Equipment.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.EquipmentCode).ToListAsync(t);var jobs=await db.ProductionJobs.AsNoTracking().Where(x=>x.AssignedEquipmentId!=null&&x.Status!=ProductionJobStatus.Completed&&x.Status!=ProductionJobStatus.Failed&&(x.PlannedStartUtc==null||x.PlannedStartUtc<u)&&(x.PlannedEndUtc==null||x.PlannedEndUtc>f)).ToListAsync(t);return Result.Success<IReadOnlyList<EquipmentCapacityView>>(equipment.Select(e=>Capacity(e.Id,e.EquipmentCode,e.Name,jobs)).ToArray());},ct);
 private static EquipmentCapacityView Capacity(Guid id,string code,string name,IReadOnlyList<ProductionJob>jobs){List<ProductionJob>j=jobs.Where(x=>x.AssignedEquipmentId==id).ToList();return new(id,code,name,j.Count(x=>x.Status is ProductionJobStatus.Planned or ProductionJobStatus.Ready),j.Count(x=>x.Status==ProductionJobStatus.InProgress),j.FirstOrDefault(x=>x.Status==ProductionJobStatus.InProgress)?.Id,j.Count==0?null:j.Min(x=>x.PlannedStartUtc),j.Count==0?null:j.Max(x=>x.PlannedEndUtc));}
 public Task<Result<IReadOnlyList<ProductionHistoryView>>>HistoryAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.ProductionJobs.AnyAsync(x=>x.Id==id,t))return Result.Failure<IReadOnlyList<ProductionHistoryView>>(ProductionErrors.NotFound);return Result.Success<IReadOnlyList<ProductionHistoryView>>((await db.ProductionJobHistory.AsNoTracking().Where(x=>x.ProductionJobId==id).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(x=>new ProductionHistoryView(x.Id,x.EventType,x.ActorUserId,x.OccurredAtUtc,x.Summary)).ToArray());},ct);
 public Task<Result<ProductionJobView>>PlanAsync(Guid id,PlanProductionJobCommand c,CancellationToken ct)=>Mutate(id,"Planned",c.Version,(j,n)=>j.Plan(c.Priority,c.PlannedStartUtc,c.PlannedEndUtc,c.QueuePosition,c.Version,n),null,ct);
 public Task<Result<ProductionJobView>>AssignOperatorAsync(Guid id,AssignOperatorCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await ValidOperator(c.OperatorUserId,t))return Result.Failure<ProductionJobView>(ProductionErrors.InvalidOperator);return await MutateCore(id,"OperatorAssigned",c.Version,(j,n)=>j.AssignOperator(c.OperatorUserId,c.Version,n),c.OperatorUserId.ToString(),t);},ct);
 public Task<Result<ProductionJobView>>AssignEquipmentAsync(Guid id,AssignEquipmentCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);if(c.EquipmentId is not null&&!await Compatible(j.JobType,c.EquipmentId.Value,t))return Result.Failure<ProductionJobView>(ProductionErrors.IncompatibleEquipment);Result r=j.AssignEquipment(c.EquipmentId,c.Version,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,"EquipmentAssigned",c.EquipmentId?.ToString());Log("production.equipment.assigned",j.Id);return Result.Success(View(j));},ct);
 public Task<Result<ProductionJobView>>StartAsync(Guid id,long version,CancellationToken ct)=>Mutate(id,"Started",version,(j,n)=>j.Start(version,n),null,ct);public Task<Result<ProductionJobView>>CompleteAsync(Guid id,CompleteProductionJobCommand c,CancellationToken ct)=>Mutate(id,"Completed",c.Version,(j,n)=>j.Complete(c.QuantityCompleted,c.Notes,c.Version,n),c.Notes,ct);public Task<Result<ProductionJobView>>FailAsync(Guid id,ProductionReasonCommand c,CancellationToken ct)=>Mutate(id,"Failed",c.Version,(j,n)=>j.Fail(c.Reason,c.Version,n),c.Reason,ct);public Task<Result<ProductionJobView>>SuspendAsync(Guid id,ProductionReasonCommand c,CancellationToken ct)=>Mutate(id,"Suspended",c.Version,(j,n)=>j.Suspend(c.Reason,c.Version,n),c.Reason,ct);public Task<Result<ProductionJobView>>ResumeAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);if(j.AssignedOperatorUserId is null||!await ValidOperator(j.AssignedOperatorUserId.Value,t)||j.AssignedEquipmentId is not null&&!await Compatible(j.JobType,j.AssignedEquipmentId.Value,t))return Result.Failure<ProductionJobView>(ProductionErrors.AssignmentRequired);Result r=j.Resume(version,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,"Resumed",null);Log("production.job.resumed",j.Id);return Result.Success(View(j));},ct);
 private Task<Result<ProductionJobView>>Mutate(Guid id,string evt,long version,Func<ProductionJob,DateTimeOffset,Result>change,string?summary,CancellationToken ct)=>tx.ExecuteAsync(t=>MutateCore(id,evt,version,change,summary,t),ct);private async Task<Result<ProductionJobView>>MutateCore(Guid id,string evt,long version,Func<ProductionJob,DateTimeOffset,Result>change,string?summary,CancellationToken t){ProductionJob?j=await db.ProductionJobs.SingleOrDefaultAsync(x=>x.Id==id,t);if(j is null)return Result.Failure<ProductionJobView>(ProductionErrors.NotFound);Result r=change(j,Now);if(r.IsFailure)return Result.Failure<ProductionJobView>(r.Error);History(j,evt,summary);Log($"production.job.{evt.ToLowerInvariant()}",j.Id);return Result.Success(View(j));}
 private async Task<bool>ValidOperator(Guid user,CancellationToken t)=>await db.ApplicationUsers.AnyAsync(x=>x.Id==user&&x.AccountState==Domain.Security.UserAccountState.Active,t)&&await db.UserCompanies.AnyAsync(x=>x.UserId==user&&x.ValidFromUtc<=Now&&(x.ValidToUtc==null||x.ValidToUtc>Now),t)&&await(from ur in db.UserRoles join rp in db.RolePermissions on ur.RoleId equals rp.RoleId join p in db.Permissions on rp.PermissionId equals p.Id where ur.UserId==user&&ur.ValidFromUtc<=Now&&(ur.ValidToUtc==null||ur.ValidToUtc>Now)&&p.Code=="production.execute" select ur.Id).AnyAsync(t);private async Task<bool>Compatible(ProductionJobType type,Guid equipment,CancellationToken t){var e=await db.Equipment.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==equipment&&x.IsActive,t);if(e is null||e.OperationalStatusCode is not("AVAILABLE" or "READY"))return false;string code=e.EquipmentTypeCode;return type switch{ProductionJobType.DesignPreparation=>false,ProductionJobType.Print=>code.Contains("PRINT",StringComparison.OrdinalIgnoreCase),ProductionJobType.HeatPress=>code.Contains("HEAT",StringComparison.OrdinalIgnoreCase)||code.Contains("PRESS",StringComparison.OrdinalIgnoreCase),_=>false};}
 private void History(ProductionJob j,string type,string?summary)=>db.ProductionJobHistory.Add(ProductionJobHistory.Create(Company,j.Id,type,Actor,Now,summary));private void Log(string action,Guid id)=>audit.Write(new(action,"production_job",id.ToString(),ChangeKind:AuditChangeKind.Modified));private static ProductionJobView View(ProductionJob j)=>new(j.Id,j.OrderId,j.OrderItemId,j.PrintOperationId,j.ReproductionRequestId,j.SourceProductionJobId,j.RootProductionJobId,j.ReproductionDepth,j.JobType,j.Status,j.Priority,j.QueuePosition,j.AssignedOperatorUserId,j.AssignedEquipmentId,j.PlannedStartUtc,j.PlannedEndUtc,j.StartedAtUtc,j.CompletedAtUtc,j.FailureReason,j.SuspensionReason,j.ArtworkVersionId,j.FileVersionId,j.QuantityCompleted,j.ExecutionNotes,j.Version);
}
#pragma warning restore CA1862,CA1725
